    /**
     * Tests getting all InferenceEndpoints.
     *
     * @return    Collection
     */
    public List<InferenceEndpoint> testGetAll() throws Throwable {
    LOGGER.info( "InferenceEndpointTest:testGetAll() - Retrieving Collection of InferenceEndpoints:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all InferenceEndpoint : " );
    List<InferenceEndpoint> collection  = null;

    try {
        // call the static get method on the InferenceEndpointService
        collection = service.getAllInferenceEndpoint();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            InferenceEndpoint currEntity  = null;
            Iterator<InferenceEndpoint> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getInferenceEndpointId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

